margin_0_padding_0_box_sizing_border_box:
*{margin:0;padding:0;box-sizing:border-box}
body{font-family:Inter,sans-serif;background:#06060c;color:#eeeef2;overflow-x:hidden}
::-webkit-scrollbar{width:4px}::-webkit-scrollbar-thumb{background:#d4a37344;border-radius:2px}
.nav{position:sticky;top:0;z-index:100;background:rgba(6,6,12,.92);backdrop-filter:blur(16px);border-bottom:1px solid rgba(255,255,255,.04);height:60px;display:flex;align-items:center}
.ni{max-width:1100px;margin:0 auto;padding:0 20px;width:100%;display:flex;align-items:center;justify-content:space-between}
.nav-links{display:flex;gap:16px;align-items:center}
.nav-links a{font-size:12px;color:rgba(255,255,255,.4);text-decoration:none;transition:color .3s}
.nav-links a:hover{color:#fff}
.bp{display:inline-flex;align-items:center;gap:6px;padding:10px 22px;background:#d4a373;color:#fff;border:none;border-radius:8px;font-size:12px;font-weight:600;cursor:pointer;text-decoration:none;transition:all .25s;font-family:Inter,sans-serif}
.bp:hover{filter:brightness(1.12);transform:translateY(-2px)}
.hero{min-height:80vh;display:flex;align-items:center;padding:40px 20px}
.hi{max-width:1100px;margin:0 auto;display:grid;grid-template-columns:1fr 1fr;gap:48px;align-items:center;width:100%}
.hero h1{font-family:Space Grotesk,sans-serif;font-size:44px;font-weight:700;line-height:1.1;margin-bottom:14px}
.ac{color:#d4a373}
.hero p{font-size:14px;color:rgba(255,255,255,.4);line-height:1.6;margin-bottom:24px;max-width:440px}
.him{aspect-ratio:4/3;border:1px solid rgba(255,255,255,.04);border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:80px;background:radial-gradient(ellipse,rgba(0,0,0,.03) 0%,transparent 70%)opacity:.1}
.sg{max-width:1100px;margin:0 auto;padding:60px 20px;width:100%}
.cg{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
.card{background:#121220;border:1px solid rgba(255,255,255,.04);border-radius:12px;overflow:hidden;transition:all .3s;text-decoration:none;color:inherit;display:block}
.card:hover{transform:translateY(-4px);box-shadow:0 12px 40px rgba(0,0,0,.3);border-color:#d4a37333}
.cbd{padding:18px}
.card h3{font-family:Space Grotesk,sans-serif;font-size:17px;font-weight:600}
.card p{font-size:12px;color:rgba(255,255,255,.35);line-height:1.5}
.pr{font-size:15px;font-weight:700;color:#c8a87c;font-family:Space Grotesk,sans-serif}
.wf{position:fixed;bottom:20px;right:20px;z-index:99;width:54px;height:54px;border-radius:50%;background:#25D366;display:flex;align-items:center;justify-content:center;box-shadow:0 4px 20px rgba(37,211,102,.3);transition:all .3s;text-decoration:none;color:#fff;font-size:22px}
.wf:hover{transform:scale(1.1)}
.fu{opacity:0;transform:translateY(20px);transition:all .6s ease-out}
.fu.vis{opacity:1;transform:translateY(0)}
@media(max-width:768px){.hi{grid-template-columns:1fr}.hero h1{font-size:32px}.cg{grid-template-columns:1fr}}
